import json, re

# Check if we got data
if loc_test and loc_test != '(command completed with no output)':
    clean = re.sub(r'\x1b\[[0-9;]*m', '', loc_test)
    if '(.venv)' in clean:
        clean = clean.split('(.venv)')[0].strip()
    if '\n[stderr]\n' in clean:
        clean = clean.split('\n[stderr]\n')[1].strip()
    # Find JSON
    for line in clean.split('\n'):
        line = line.strip()
        if line.startswith('{'):
            data = json.loads(line)
            print(f"Location data: {data}")
            lat = data["result"]["latitude"]
            lon = data["result"]["longitude"]
            print(f"lat={lat}, lon={lon}")
            break
else:
    print("Still no output captured")

import json, re

if test_loc and test_loc != '(command completed with no output)':
    # Clean ANSI codes
    clean = re.sub(r'\x1b\[[0-9;]*m', '', test_loc)
    # Remove [stderr] marker if present
    if '\n[stderr]\n' in clean:
        parts = clean.split('\n[stderr]\n')
        clean = parts[-1].strip()
    # Remove shell prompt
    if '(.venv)' in clean:
        clean = clean.split('(.venv)')[0].strip()
    # Find JSON
    for line in clean.split('\n'):
        line = line.strip()
        if line.startswith('{'):
            data = json.loads(line)
            print(f"SUCCESS! Data: {data}")
            break
    else:
        print(f"No JSON line found in: {clean[:200]}")
else:
    print("Still no output - need different approach entirely")
